```javascript
({onInit, getContacts, editContact}) => {
    this.getContacts();
};

getContacts() {
    const action = this.createAction(
        "c.getContacts",
        { accountId: this.accountId }
    );

    action.setCallback(this, (response) => {
        const state = response.getState();
        if (state === "SUCCESS") {
            this.contacts = response.getReturnValue();
        } else {
            console.error("Error fetching contacts:", response.getError());
        }
    });

    $A.enqueueAction(action);
}

editContact() {
    const contact = this.findContact(this.contactId);
    if (contact) {
        this.dispatchEvent(new CustomEvent("editcontact", { detail: contact }));
    }
}

findContact(id) {
    return this.contacts.find((contact) => contact.Id === id);
}
