Here's a Swift program that identifies and corrects homophones in a given passage:

```swift
import Foundation

func correctHomophones(in passage: String) -> String {
    let words = passage.components(separatedBy: .whitespacesAndNewlines)
    var correctedPassage = ""

    for word in words {
        let correctedWord = correctHomophone(word)
        if correctedWord != nil {
            correctedPassage += correctedWord! + " "
        } else {
            correctedPassage += word + " "
        }
    }

    return correctedPassage.trimmingCharacters(in: .whitespacesAndNewlines)
}

func correctHomophone(_ word: String) -> String? {
    let homophones = [
        ("their", "there"),
        ("they're", "there"),
        ("you're", "your"),
        ("to", "too"),
        ("two", "too"),
        ("we", "way"),
        ("were", "where"),
        ("what", "whet"),
        ("when", "wagon"),
        ("which", "witch")
    ]

    for (correctWord, incorrectWord) in homophones {
        if word.lowercased() == incorrectWord.lowercased() {
            return correctWord
        }
    }

    return nil
}

